settings.custom_liquid:
{% assign current_product = closest.product %}
{% assign product_types = current_product.metafields.custom.type.value %}

{% if product_types != blank %}
  <div class="product-type-labels">
    {% for type in product_types %}
      <span class="product-type-label">{{ type }}</span>
    {% endfor %}
  </div>
{% endif %}
